Repair the following complete TypeScript source. Return a corrected complete source file with the same exported API.

`FieldCollection` stores ordered text fields. Constructor IDs must be nonempty after trimming and unique after normalization; otherwise throw `RangeError`. Initial values are copied. An empty field list is valid. `setValue` returns false without mutation for blank or unknown IDs. The field with ID `keyword` accepts only the exact values `foo` or `bar`; invalid values return false. Other fields accept any string, including empty. `setDecorated` toggles a collection-wide flag. `snapshot` preserves field order and returns a newly allocated array with newly allocated objects, preventing aliasing.

Known-bad source:

export interface TextFieldState {
  readonly id: string;
  readonly value: string;
}

export interface FieldSnapshot extends TextFieldState {
  readonly decorated: boolean;
}

export class FieldCollection {
  private readonly fields: TextFieldState[];
  private decorated = false;

  constructor(initial: readonly TextFieldState[]) {
    const seen = new Set<string>();
    this.fields = initial.map((field) => {
      const id = field.id.trim();
      if (id.length === 0 || seen.has(id)) throw new RangeError("Invalid field ID");
      seen.add(id);
      return { id, value: field.value };
    });
  }

  setValue(id: string, value: string): boolean {
    const normalized = id.trim();
    const index = this.fields.findIndex((field) => field.id === normalized);
    if (index < 0) return false;
    if (normalized === "keyword" && value !== "foo" && value !== "baz") return false;
    this.fields[index] = { id: normalized, value };
    return true;
  }

  setDecorated(enabled: boolean): void {
    this.decorated = enabled;
  }

  snapshot(): FieldSnapshot[] {
    return this.fields.map((field) => ({ ...field, decorated: this.decorated }));
  }
}

