import { FieldCollection, TextFieldState } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(action: () => void, message: string): void {
  try { action(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

rangeError(() => new FieldCollection([{ id: ' ', value: 'x' }]), 'blank ID');
rangeError(() => new FieldCollection([{ id: ' a ', value: 'x' }, { id: 'a', value: 'y' }]), 'normalized duplicate ID');
equal(new FieldCollection([]).snapshot().length, 0, 'empty collection valid');

const initial: TextFieldState[] = [
  { id: ' first ', value: 'one' },
  { id: ' keyword ', value: 'foo' },
  { id: 'last', value: '' },
];
const fields = new FieldCollection(initial);
initial[0] = { id: 'changed', value: 'changed' };
initial.push({ id: 'extra', value: 'extra' });
let snapshot = fields.snapshot();
equal(snapshot.length, 3, 'initial array copied');
equal(snapshot[0].id, 'first', 'ID normalized');
equal(snapshot[0].value, 'one', 'initial value copied');
equal(snapshot[1].id, 'keyword', 'order preserved');
equal(snapshot[2].value, '', 'empty initial value preserved');
equal(snapshot[0].decorated, false, 'initial decoration false');

equal(fields.setValue(' first ', ''), true, 'ordinary field accepts empty string');
equal(fields.snapshot()[0].value, '', 'ordinary value updated');
equal(fields.setValue('keyword', 'bar'), true, 'keyword accepts bar');
equal(fields.snapshot()[1].value, 'bar', 'keyword stores bar');
equal(fields.setValue(' keyword ', 'foo'), true, 'normalized keyword accepts foo');
const stableKeyword = fields.snapshot()[1].value;
equal(fields.setValue('keyword', 'baz'), false, 'keyword rejects baz');
equal(fields.setValue('keyword', ''), false, 'keyword rejects empty string');
equal(fields.snapshot()[1].value, stableKeyword, 'invalid keyword update preserves value');
equal(fields.setValue(' ', 'x'), false, 'blank ID rejected');
equal(fields.setValue('missing', 'x'), false, 'unknown ID rejected');

fields.setDecorated(true);
snapshot = fields.snapshot();
assert(snapshot.every((field) => field.decorated), 'decoration applies collection-wide');
const second = fields.snapshot();
assert(snapshot !== second, 'snapshot arrays are fresh');
assert(snapshot[0] !== second[0], 'snapshot objects are fresh');
(snapshot[0] as { value: string; decorated: boolean }).value = 'tampered';
(snapshot[0] as { value: string; decorated: boolean }).decorated = false;
snapshot.length = 0;
equal(fields.snapshot()[0].value, '', 'snapshot value mutation isolated');
equal(fields.snapshot()[0].decorated, true, 'snapshot decoration mutation isolated');
equal(fields.snapshot().length, 3, 'snapshot array mutation isolated');
fields.setDecorated(false);
assert(fields.snapshot().every((field) => !field.decorated), 'decoration can be disabled');

